-- Généré par tools/extract_design_content.py — ne pas éditer à la main.
-- Source : bloc LESSONS de la variante « Krezus App -lovable-.dc.html ».
-- Les 4 premières leçons sont gratuites ; les suivantes sont derrière le paywall.

insert into public.lessons (position, title_fr, duration_label, paragraphs_fr,
  examples_fr, quiz_fr, is_free)
values
  (1, 'C’est quoi une action ?', '2 min', '["Une action est une part de propriété d’une entreprise. En posséder une, même une fraction, fait de vous un actionnaire : un co-propriétaire.", "Si l’entreprise crée de la valeur, votre part peut en prendre aussi. Si elle en perd, votre part peut baisser. C’est le principe du risque."]'::jsonb, '["Avec 0,45 action Nvidia, vous possédez une petite part de chaque puce vendue, de chaque brevet déposé, de chaque data center équipé.", "Si Nvidia double de valeur, vos 0,45 action valent deux fois plus — sans que vous ayez rien à faire."]'::jsonb, '{"q": "Que possédez-vous en achetant une action ?", "opts": ["Un prêt fait à l’entreprise", "Une part de propriété de l’entreprise", "Un abonnement à ses produits"], "a": 1, "why": "Une action est une part de propriété : vous devenez actionnaire, pas prêteur."}'::jsonb, true),
  (2, 'Le dividende', '3 min', '["Certaines entreprises reversent une partie de leurs bénéfices à leurs actionnaires : c’est le dividende, souvent versé chaque trimestre ou chaque année.", "Toutes ne le font pas. Les entreprises en forte croissance préfèrent réinvestir leurs bénéfices."]'::jsonb, '["Air Liquide verse un dividende d’environ 2,9 % par an. Avec 0,21 action, vous recevrez votre première part de bénéfices en mai prochain.", "Une entreprise qui verse 40 % de ses bénéfices en dividende garde les 60 % restants pour investir dans sa croissance."]'::jsonb, '{"q": "D’où vient le dividende ?", "opts": ["Des bénéfices de l’entreprise", "D’un prêt bancaire", "De vos propres versements"], "a": 0, "why": "Le dividende est une part des bénéfices reversée aux actionnaires."}'::jsonb, true),
  (3, 'La diversification', '3 min', '["Mettre tous ses œufs dans le même panier, c’est risqué. Diversifier, c’est répartir son investissement entre plusieurs entreprises, secteurs et pays.", "Quand l’un baisse, l’autre peut monter : votre portefeuille devient plus stable dans le temps."]'::jsonb, '["Nvidia (tech, États-Unis) + Air Liquide (industrie, France) : deux moteurs très différents. C’est déjà un début de diversification.", "Un portefeuille concentré sur une seule action peut perdre 50 % en une journée ; réparti sur dix actions, l’impact d’une seule chute est amorti."]'::jsonb, '{"q": "Pourquoi diversifier son portefeuille ?", "opts": ["Pour payer moins d’impôts", "Pour réduire le risque global", "Pour gagner plus vite"], "a": 1, "why": "Répartir son investissement réduit l’impact d’une baisse isolée."}'::jsonb, true),
  (4, 'Penser long terme', '2 min', '["Sur un jour, la bourse est imprévisible. Sur dix ans, les marchés ont historiquement récompensé la patience.", "Un investisseur n’est pas un spéculateur : on ne regarde pas son portefeuille toutes les heures, on laisse le temps travailler."]'::jsonb, '["100 € investis dans les grandes entreprises mondiales en 2014 valaient environ 320 € dix ans plus tard — en traversant deux crises.", "Vendre après une baisse de 10 % pour racheter plus tard revient souvent à rater la remontée qui suit."]'::jsonb, '{"q": "Que montre l’historique des marchés sur dix ans ?", "opts": ["Une baisse continue", "La patience récompensée malgré les crises", "Une stagnation totale"], "a": 1, "why": "Sur longue durée, les marchés ont historiquement récompensé la patience."}'::jsonb, true),
  (5, 'Les intérêts composés', '3 min', '["Réinvestir vos gains fait travailler vos gains eux-mêmes. C’est un effet boule de neige : lent au début, puissant avec le temps.", "La clé n’est pas le montant, c’est la durée. Commencer tôt et ne pas interrompre."]'::jsonb, '["25 € par mois à 7 % par an : environ 4 300 € au bout de 10 ans, dont 1 300 € générés par les seuls intérêts.", "Sans réinvestir, ces mêmes 25 €/mois ne rapporteraient que les intérêts simples — environ 3 000 € de moins sur 10 ans."]'::jsonb, '{"q": "Pourquoi réinvestir ses gains ?", "opts": ["Ça ne change rien", "Les gains génèrent eux-mêmes des gains", "C’est obligatoire légalement"], "a": 1, "why": "Réinvestir crée un effet boule de neige : vos gains font travailler vos gains."}'::jsonb, false),
  (6, 'Lire un cours de bourse', '2 min', '["Un cours reflète le prix auquel acheteurs et vendeurs s’accordent, en continu. Il bouge parce que les attentes bougent.", "Ouverture, clôture, volume, variation : quatre chiffres suffisent pour lire l’essentiel."]'::jsonb, '["Nvidia « +1,4 % aujourd’hui » : l’action vaut 1,4 % de plus qu’à la clôture d’hier. Ni plus, ni moins.", "Un volume d’échanges élevé signale souvent qu’une information importante vient d’être publiée sur l’entreprise."]'::jsonb, '{"q": "Que signifie « Nvidia +1,4 % aujourd’hui » ?", "opts": ["Le titre vaut 1,4 % de plus qu’hier", "L’entreprise a gagné 1,4 % de clients", "Le dividende augmente de 1,4 %"], "a": 0, "why": "La variation compare le cours actuel à la clôture précédente."}'::jsonb, false),
  (7, 'Les indices : CAC 40 & S&P 500', '3 min', '["Un indice est un panier d’actions qui mesure la santé d’un marché entier.", "CAC 40 : les 40 plus grandes entreprises françaises. S&P 500 : les 500 plus grandes américaines."]'::jsonb, '["Quand on dit « la bourse monte », on parle en général d’un indice — pas de toutes les actions.", "Le S&P 500 a été multiplié par plus de 10 depuis 2009, malgré plusieurs crises en chemin."]'::jsonb, '{"q": "Que mesure un indice comme le CAC 40 ?", "opts": ["Une seule entreprise", "Un panier des plus grandes entreprises d’un marché", "Le taux d’intérêt de la banque centrale"], "a": 1, "why": "Un indice regroupe plusieurs entreprises pour refléter la santé d’un marché."}'::jsonb, false),
  (8, 'Les ETF, c’est quoi ?', '3 min', '["Un ETF est un fonds coté qui réplique un indice entier. Une seule part = des centaines d’entreprises.", "C’est l’outil de diversification le plus simple qui existe, avec des frais très bas."]'::jsonb, '["Un ETF S&P 500 vous rend actionnaire des 500 plus grandes entreprises américaines en un seul achat.", "Un ETF CAC 40 vous rend actionnaire des 40 plus grandes entreprises françaises en une seule ligne de portefeuille."]'::jsonb, '{"q": "Qu’achetez-vous avec une part d’ETF S&P 500 ?", "opts": ["Une seule action américaine", "Un fonds qui réplique les 500 plus grandes entreprises US", "Une obligation d’État"], "a": 1, "why": "Un ETF réplique un indice entier en un seul achat."}'::jsonb, false),
  (9, 'Le risque et la volatilité', '3 min', '["La volatilité, c’est l’ampleur des variations d’un prix. Forte volatilité = fortes émotions.", "Le risque se gère : diversification, long terme, et n’investir que l’argent dont on n’a pas besoin."]'::jsonb, '["Nvidia peut bouger de 5 % en un jour ; Air Liquide rarement plus de 2 %. Deux profils, deux rôles dans un portefeuille.", "Une action volatile n’est pas forcément mauvaise — elle demande simplement des nerfs plus solides."]'::jsonb, '{"q": "Que signifie une forte volatilité ?", "opts": ["Le prix varie peu", "Le prix varie fortement", "L’entreprise est en faillite"], "a": 1, "why": "La volatilité mesure l’ampleur des variations de prix."}'::jsonb, false),
  (10, 'Les frais, l’ennemi invisible', '2 min', '["Chaque frais prélevé est un rendement en moins — qui ne composera jamais.", "Comparer les frais avant d’investir rapporte plus que chercher « la bonne action »."]'::jsonb, '["Retirer 50 € avec 9,99 € de frais, c’est perdre 20 % de la somme. Mieux vaut retirer rarement, et en une fois.", "Deux fonds identiques à 0,2 % et 1,5 % de frais annuels peuvent finir avec un écart de plusieurs milliers d’euros après 20 ans."]'::jsonb, '{"q": "Pourquoi les frais sont-ils « l’ennemi invisible » ?", "opts": ["Ils sont illégaux", "Ils réduisent un rendement qui ne composera jamais", "Ils augmentent avec le temps"], "a": 1, "why": "Chaque frais prélevé est un rendement en moins, qui ne pourra jamais se réinvestir."}'::jsonb, false),
  (11, 'La fiscalité du débutant', '3 min', '["En France, les gains sont imposés à 30 % (la « flat tax ») au moment de la vente — pas avant.", "Tant que vous ne vendez pas, vous ne payez rien : le long terme est aussi un avantage fiscal."]'::jsonb, '["Vos 12 € de plus-value Nvidia ne seront imposés que le jour où vous vendrez.", "Conserver une action plutôt que la revendre chaque année évite de déclencher l’imposition à chaque fois."]'::jsonb, '{"q": "Quand les gains sont-ils imposés en France ?", "opts": ["Chaque année automatiquement", "Au moment de la vente", "Jamais"], "a": 1, "why": "Les gains sont imposés au moment de la vente, pas avant."}'::jsonb, false),
  (12, 'Construire son plan d’investissement', '3 min', '["Un bon plan tient en trois lignes : un objectif, un montant régulier, un horizon de temps.", "Le meilleur plan est celui que vous tiendrez sans y penser — d’où l’investissement programmé."]'::jsonb, '["« 25 € par mois pendant 10 ans pour financer mes études » : voilà un plan complet.", "Un plan écrit noir sur blanc est bien plus facile à tenir qu’une intention vague de « mieux épargner »."]'::jsonb, '{"q": "Que doit contenir un bon plan d’investissement ?", "opts": ["Un objectif, un montant régulier, un horizon", "Uniquement une somme importante", "Un secteur unique à privilégier"], "a": 0, "why": "Un plan simple tient en trois éléments : objectif, montant régulier, horizon de temps."}'::jsonb, false),
  (13, 'Action ou obligation ?', '2 min', '["Une action fait de vous propriétaire d’une entreprise. Une obligation fait de vous son créancier : vous lui prêtez de l’argent contre un intérêt fixe.", "L’action peut monter beaucoup plus haut… mais aussi baisser davantage. L’obligation est plus prévisible, avec un rendement généralement plus faible."]'::jsonb, '["Prêter 1 000 € à l’État français à 3 % par an, c’est une obligation : vous récupérez votre capital à l’échéance, plus les intérêts.", "Acheter une action Nvidia, c’est parier sur sa croissance future — sans garantie de retour, mais sans plafond non plus."]'::jsonb, '{"q": "Quelle est la vraie différence entre action et obligation ?", "opts": ["Aucune, ce sont des synonymes", "L’action rend propriétaire, l’obligation rend créancier", "L’obligation rapporte toujours plus"], "a": 1, "why": "L’actionnaire possède une part de l’entreprise ; l’obligataire lui a simplement prêté de l’argent."}'::jsonb, false),
  (14, 'L’investissement programmé (DCA)', '2 min', '["Le Dollar-Cost Averaging consiste à investir un même montant à intervalles réguliers, plutôt qu’une grosse somme d’un coup.", "Cette méthode lisse le prix d’achat moyen dans le temps et retire la pression de « trouver le bon moment »."]'::jsonb, '["25 € investis chaque mois sur Nvidia, que le cours monte ou baisse : vous achetez parfois cher, parfois moins cher — en moyenne, un prix raisonnable.", "Un investisseur qui attend « le bon moment » depuis 2020 a probablement raté une hausse de plus de 150 % sur les indices mondiaux."]'::jsonb, '{"q": "Quel est l’avantage principal du DCA ?", "opts": ["Garantir un gain", "Lisser le prix d’achat moyen dans le temps", "Éviter totalement les baisses"], "a": 1, "why": "En investissant régulièrement, on achète à des prix variés, ce qui moyenne le coût d’entrée sans avoir à deviner le bon moment."}'::jsonb, false),
  (15, 'Comprendre le PER', '3 min', '["Le PER (Price Earnings Ratio) compare le prix d’une action à son bénéfice par action. Il indique combien d’années de bénéfices vous payez.", "Un PER élevé signifie que le marché attend une forte croissance future ; un PER bas peut signaler une action délaissée — ou en difficulté."]'::jsonb, '["Une action à 100 € qui gagne 5 € par an a un PER de 20 : vous payez 20 fois son bénéfice annuel.", "Nvidia affiche historiquement un PER élevé car les investisseurs parient sur sa croissance dans l’IA ; une entreprise industrielle mature aura souvent un PER plus bas."]'::jsonb, '{"q": "Que mesure le PER ?", "opts": ["Le montant du dividende versé", "Le nombre d’années de bénéfices que vaut le prix de l’action", "Le risque de faillite de l’entreprise"], "a": 1, "why": "Le PER rapporte le prix de l’action à son bénéfice annuel par action."}'::jsonb, false),
  (16, 'Lire un bilan simplement', '3 min', '["Un bilan liste ce qu’une entreprise possède (actifs) et ce qu’elle doit (dettes). La différence, c’est ses capitaux propres.", "Une entreprise en bonne santé a généralement plus d’actifs que de dettes, et des capitaux propres qui augmentent d’année en année."]'::jsonb, '["Air Liquide possède des usines et des brevets valant des milliards : ce sont ses actifs, financés en partie par de la dette et en partie par ses actionnaires.", "Une dette qui dépasse largement les actifs est un signal d’alerte, même si le cours de l’action semble attractif."]'::jsonb, '{"q": "Que représentent les capitaux propres ?", "opts": ["La différence entre actifs et dettes", "Le chiffre d’affaires annuel", "Le prix de l’action en bourse"], "a": 0, "why": "Les capitaux propres sont ce qu’il resterait aux actionnaires si l’entreprise vendait tous ses actifs et remboursait toutes ses dettes."}'::jsonb, false),
  (17, 'Le chiffre d’affaires n’est pas le bénéfice', '2 min', '["Le chiffre d’affaires, c’est tout ce qu’une entreprise encaisse en vendant ses produits. Le bénéfice, c’est ce qu’il reste après avoir payé toutes ses charges.", "Une entreprise peut afficher un chiffre d’affaires énorme et pourtant perdre de l’argent si ses coûts sont trop élevés."]'::jsonb, '["Une chaîne qui vend 10 millions d’euros de produits mais dépense 11 millions en salaires, loyers et matières premières est déficitaire malgré un chiffre d’affaires impressionnant.", "LVMH affiche à la fois un chiffre d’affaires et une marge bénéficiaire élevés : c’est ce second chiffre qui rassure vraiment les investisseurs."]'::jsonb, '{"q": "Une entreprise avec un chiffre d’affaires énorme est-elle forcément rentable ?", "opts": ["Oui, toujours", "Non, tout dépend de ses charges", "Seulement si elle est cotée au CAC 40"], "a": 1, "why": "Le bénéfice ne dépend pas que des ventes, mais aussi des coûts à payer pour les réaliser."}'::jsonb, false),
  (18, 'Marché primaire vs marché secondaire', '2 min', '["Le marché primaire, c’est quand une entreprise vend ses actions pour la première fois (l’introduction en bourse). Le marché secondaire, c’est l’échange entre investisseurs ensuite.", "Quand vous achetez une action Nvidia aujourd’hui, vous l’achetez à un autre investisseur — pas directement à Nvidia."]'::jsonb, '["L’introduction en bourse d’une entreprise est un événement rare ; l’essentiel des échanges quotidiens se fait ensuite sur le marché secondaire.", "Krezus vous permet d’acheter et vendre sur le marché secondaire, aux prix fixés en continu par l’offre et la demande."]'::jsonb, '{"q": "Que se passe-t-il quand vous achetez une action Nvidia aujourd’hui ?", "opts": ["Vous l’achetez directement à Nvidia", "Vous l’achetez à un autre investisseur sur le marché secondaire", "Vous participez à son introduction en bourse"], "a": 1, "why": "Sauf lors d’une introduction en bourse, les échanges se font entre investisseurs sur le marché secondaire."}'::jsonb, false),
  (19, 'Qu’est-ce qu’une capitalisation boursière ?', '2 min', '["La capitalisation boursière, c’est la valeur totale d’une entreprise en bourse : le prix d’une action multiplié par le nombre total d’actions.", "Elle permet de comparer la taille de deux entreprises, même si leurs cours par action sont très différents."]'::jsonb, '["Une action à 900 € avec 20 millions d’actions vaut moins en capitalisation qu’une action à 50 € avec 2 milliards d’actions.", "Nvidia a dépassé les 3 000 milliards de dollars de capitalisation en 2024 — l’une des plus fortes valorisations jamais atteintes."]'::jsonb, '{"q": "Comment calcule-t-on la capitalisation boursière ?", "opts": ["Prix de l’action × nombre total d’actions", "Chiffre d’affaires × 10", "Bénéfice annuel ÷ dividende"], "a": 0, "why": "La capitalisation reflète la valeur totale de l’entreprise sur le marché, pas seulement le prix d’une action."}'::jsonb, false),
  (20, 'Le biais du troupeau', '2 min', '["Le biais du troupeau pousse à acheter parce que « tout le monde achète », et à vendre parce que « tout le monde panique » — sans réfléchir soi-même.", "Ce comportement amplifie les bulles et les krachs. Les investisseurs les plus sereins pensent à contre-courant."]'::jsonb, '["Acheter une action juste parce qu’elle « buzz » sur les réseaux sociaux, sans en comprendre l’activité, est un exemple classique du biais du troupeau.", "Hercule vous alerte si votre comportement ressemble à un suivi de tendance plutôt qu’à une décision réfléchie."]'::jsonb, '{"q": "Qu’est-ce que le biais du troupeau ?", "opts": ["Suivre la foule sans réflexion personnelle", "Diversifier son portefeuille", "Investir sur le long terme"], "a": 0, "why": "Ce biais consiste à agir comme la majorité, par peur de rater quelque chose, plutôt que sur une analyse propre."}'::jsonb, false),
  (21, 'La peur de rater quelque chose (FOMO)', '2 min', '["Le FOMO pousse à acheter en urgence après une forte hausse, par peur de « rater le train ». C’est souvent le pire moment pour investir.", "Une décision prise sous le coup de l’émotion est rarement une bonne décision financière."]'::jsonb, '["Après une hausse de 20 % en une semaine, acheter dans la précipitation revient souvent à acheter au prix le plus haut.", "Krezus mesure votre score FOMO pour vous aider à repérer ces réflexes avant d’agir."]'::jsonb, '{"q": "Pourquoi le FOMO est-il risqué en investissement ?", "opts": ["Il pousse à acheter après une forte hausse, souvent au plus mauvais moment", "Il rend les décisions plus rationnelles", "Il n’a aucun effet réel"], "a": 0, "why": "Acheter dans la précipitation après une hausse revient souvent à payer le prix le plus élevé."}'::jsonb, false),
  (22, 'Accepter la perte, un jour normal en bourse', '2 min', '["Une action qui baisse un jour donné ne signifie pas un mauvais investissement : c’est la volatilité normale des marchés.", "Vendre en panique après une baisse transforme une perte temporaire en perte définitive."]'::jsonb, '["Une action peut perdre 3 % un lundi et regagner 4 % le mardi suivant : réagir à chaque mouvement quotidien est rarement utile.", "Les investisseurs qui ont vendu en panique lors des baisses de 2020 ont manqué la reprise qui a suivi quelques mois plus tard."]'::jsonb, '{"q": "Que faire face à une baisse ponctuelle du marché ?", "opts": ["Vendre immédiatement pour limiter les pertes", "Garder son calme et penser long terme", "Investir davantage sans réfléchir"], "a": 1, "why": "Les baisses ponctuelles font partie du fonctionnement normal des marchés ; vendre en panique fige une perte qui aurait pu se résorber."}'::jsonb, false),
  (23, 'Se constituer une épargne de précaution', '2 min', '["Avant d’investir, il est conseillé de garder de côté 3 à 6 mois de dépenses courantes, facilement accessibles.", "Cette épargne évite de devoir vendre ses actions au mauvais moment en cas d’imprévu."]'::jsonb, '["Une panne de voiture à 800 € ne devrait pas obliger à vendre des actions en pleine baisse du marché.", "Avec 1 500 € de dépenses mensuelles, une épargne de précaution représenterait entre 4 500 € et 9 000 €."]'::jsonb, '{"q": "À quoi sert une épargne de précaution ?", "opts": ["À investir davantage en bourse", "À éviter de vendre ses actions en cas d’imprévu", "À payer moins d’impôts"], "a": 1, "why": "Elle couvre les imprévus sans avoir à liquider des placements, parfois au pire moment."}'::jsonb, false),
  (24, 'Budget : dépenser, épargner, investir', '2 min', '["Une règle simple répartit les revenus en trois blocs : les dépenses essentielles, l’épargne de précaution, et l’investissement long terme.", "Même de petits montants investis régulièrement font une vraie différence sur dix ou vingt ans."]'::jsonb, '["Une règle courante : 50 % dépenses essentielles, 30 % envies, 20 % épargne et investissement.", "Investir 25 € par mois dès 20 ans construit un capital bien plus important qu’investir 100 € par mois à partir de 35 ans, grâce au temps."]'::jsonb, '{"q": "Pourquoi commencer à investir tôt, même avec de petits montants ?", "opts": ["Le temps amplifie l’effet des intérêts composés", "Cela évite de payer des impôts", "Cela garantit un gain immédiat"], "a": 0, "why": "Plus la durée d’investissement est longue, plus les intérêts composés ont le temps de produire leur effet."}'::jsonb, false),
  (25, 'Que fait vraiment une entreprise cotée ?', '2 min', '["Derrière chaque action se cache une vraie entreprise, avec des salariés, des produits et des clients.", "Comprendre ce que fait une entreprise avant d’investir permet de savoir pourquoi son cours peut monter — ou baisser."]'::jsonb, '["Nvidia ne « monte » pas par magie : elle vend des puces utilisées dans l’intelligence artificielle, de plus en plus demandées.", "Air Liquide ne fait pas de gros titres, mais fournit des gaz industriels essentiels à des usines du monde entier — un métier discret et stable."]'::jsonb, '{"q": "Pourquoi comprendre l’activité d’une entreprise avant d’investir ?", "opts": ["Ce n’est pas nécessaire, seul le cours compte", "Cela aide à comprendre pourquoi le cours évolue", "Cela garantit un gain"], "a": 1, "why": "Le cours d’une action reflète, à terme, la santé réelle de l’activité de l’entreprise."}'::jsonb, false),
  (26, 'Les secteurs d’activité', '2 min', '["Les entreprises cotées sont classées par secteurs : technologie, santé, industrie, luxe, énergie…", "Chaque secteur réagit différemment à l’économie : la tech peut s’envoler en période d’innovation, l’énergie suit les prix des matières premières."]'::jsonb, '["Nvidia (technologie), LVMH (luxe) et Air Liquide (industrie) représentent trois secteurs très différents dans un même portefeuille.", "En période de hausse des taux d’intérêt, les valeurs technologiques réagissent souvent plus fortement que les valeurs industrielles."]'::jsonb, '{"q": "Pourquoi les secteurs sont-ils utiles à connaître ?", "opts": ["Ils garantissent un rendement fixe", "Ils réagissent différemment aux mêmes événements économiques", "Ils sont tous corrélés de la même façon"], "a": 1, "why": "Connaître les secteurs aide à comprendre pourquoi deux actions peuvent réagir différemment à la même actualité."}'::jsonb, false),
  (27, 'Les entreprises familiales vs les multinationales', '2 min', '["Certaines entreprises cotées restent dirigées par leur famille fondatrice ; d’autres sont détenues par des millions d’actionnaires dispersés dans le monde.", "Ce mode de gouvernance influence parfois les décisions : une entreprise familiale pense souvent sur des décennies, pas seulement au trimestre suivant."]'::jsonb, '["LVMH reste dirigée par la famille Arnault, actionnaire majoritaire, ce qui favorise une vision à très long terme.", "D’autres grandes entreprises n’ont aucun actionnaire familial dominant : les décisions y sont prises collectivement par un conseil d’administration."]'::jsonb, '{"q": "Quel est un avantage souvent associé aux entreprises familiales cotées ?", "opts": ["Une vision à long terme plus marquée", "Des dividendes obligatoires plus élevés", "Une absence totale de risque"], "a": 0, "why": "Une famille fondatrice, souvent actionnaire de long terme, a tendance à privilégier la pérennité sur la performance trimestrielle."}'::jsonb, false)
on conflict (position) do update set
  title_fr = excluded.title_fr,
  paragraphs_fr = excluded.paragraphs_fr,
  examples_fr = excluded.examples_fr,
  quiz_fr = excluded.quiz_fr;
